#pragma once
#include "df32.cuh"
#define BF_PI 3.14159265358979323846f
__device__ __forceinline__ float bf_wrap(float x){x=fmodf(x+BF_PI,2*BF_PI);if(x<0)x+=2*BF_PI;return x-BF_PI;}
__device__ __forceinline__ void bf_polar(unsigned af,float alpha,float&cl,float&cd){unsigned off=bem_af_offset[af],n=bem_af_count[af];float x=bf_wrap(alpha)*(180.0f/BF_PI);unsigned lo=0,hi=n-1;if(x<=float(bem_alpha_deg[off])){cl=float(bem_cl[off]);cd=float(bem_cd[off]);return;}if(x>=float(bem_alpha_deg[off+n-1])){cl=float(bem_cl[off+n-1]);cd=float(bem_cd[off+n-1]);return;}unsigned bin=(unsigned)fminf(720,fmaxf(0,floorf((x+180)*2)));lo=(unsigned)bem_polar_lut[af*721u+bin]-off;hi=lo+1;while(lo>0&&float(bem_alpha_deg[off+lo])>x){--lo;--hi;}while(hi<n-1&&float(bem_alpha_deg[off+hi])<=x){++lo;++hi;}float x0=float(bem_alpha_deg[off+lo]),x1=float(bem_alpha_deg[off+hi]),w=(x-x0)/(x1-x0);cl=float(bem_cl[off+lo])+w*float(bem_cl[off+hi]-bem_cl[off+lo]);cd=float(bem_cd[off+lo])+w*float(bem_cd[off+hi]-bem_cd[off+lo]);}
__device__ __forceinline__ float bf_residual(float phi,float vx,float vy,float theta,unsigned node,int&valid){if(fabsf(vx)<1e-3f||fabsf(vy)<1e-3f||fabsf(phi)<1e-15f){valid=1;return 0;}float cl,cd;bf_polar(bem_node_afid[node],phi-theta,cl,cd);float s=sinf(phi),c=cosf(phi),as=fabsf(s),ft=1,fh=1;if(as>0){ft=(2/BF_PI)*acosf(fminf(1,expf(-float(bem_node_tip_const[node])/as)));fh=(2/BF_PI)*acosf(fminf(1,expf(-float(bem_node_hub_const[node])/as)));}float F=fmaxf(ft*fh,1e-4f),sigma=3*float(bem_node_chord[node])/(2*BF_PI*float(bem_node_r[node])),cn=cl*c,ct=cl*s,k=sigma*cn/(4*F*s*s),kp;if(fabsf(c)<1e-15f)kp=copysignf(1e6f,ct*s)*copysignf(1,vx);else{kp=sigma*ct/(4*F*s*c);if(vx<0)kp=-kp;}bool momentum=(phi>0&&vx>=0)||(phi<0&&vx<0);valid=1;float a;if(momentum){if(k<=2.0f/3){a=k/(1+k);if(k<-1)valid=0;}else{float t=2*F*k,g1=t-(10.0f/9-F),g2=t-(4.0f/3-F)*F,g3=t-(25.0f/9-2*F);a=fabsf(g3)<1e-6f?1-.5f/sqrtf(g2):(g1-sqrtf(fabsf(g2)))/g3;}return s/(1-a)-c/(vy/vx)*(1-kp);}a=k/(k-1);if(k<=1)valid=0;return s*(1-k)-c/(vy/vx)*(1-kp);}
__device__ int bf_bisect(float vx,float vy,float th,unsigned node,float a,float b,float&root){int va,vb,vm;float fa=bf_residual(a,vx,vy,th,node,va),fb=bf_residual(b,vx,vy,th,node,vb);if(!isfinite(fa)||!isfinite(fb)||signbit(fa)==signbit(fb))return 0;for(int k=0;k<32;k++){float m=.5f*(a+b),fm=bf_residual(m,vx,vy,th,node,vm);if(!isfinite(fm))return 0;if(fabsf(fm)<2e-6f||fabsf(b-a)<2e-7f){root=m;return vm;}if(signbit(fa)!=signbit(fm))b=m;else{a=m;fa=fm;}}root=.5f*(a+b);bf_residual(root,vx,vy,th,node,vm);return vm;}
__device__ int bf_scan(float vx,float vy,float th,float hint,unsigned node,float lo,float hi,int maxcells,float&root){const int cells=512;int center=(int)floorf((hint-lo)/(hi-lo)*cells);center=max(0,min(cells-1,center));int left=center,right=center+1,have=0,scanned=0;float best=0,bd=INFINITY;while((left>=0||right<cells)&&scanned<maxcells){float dl=INFINITY,dr=INFINITY;if(left>=0)dl=fabsf(bf_wrap(lo+(hi-lo)*(left+1)/cells-hint));if(right<cells)dr=fabsf(bf_wrap(lo+(hi-lo)*right/cells-hint));if(have&&bd<=fminf(dl,dr)){root=best;return 1;}int cell=dl<=dr?left--:right++;scanned++;float a=lo+(hi-lo)*cell/cells,b=lo+(hi-lo)*(cell+1)/cells,x;if(bf_bisect(vx,vy,th,node,a,b,x)){int v;float f=bf_residual(x,vx,vy,th,node,v);float d=fabsf(bf_wrap(x-hint));if(v&&fabsf(f)<2e-4f&&d<bd){best=x;bd=d;have=1;}}}if(have&&left<0&&right>=cells){root=best;return 1;}return 0;}
__device__ int bf_solve(float vx,float vy,float th,float hint,unsigned node,int maxcells,float&root){if(fabsf(vx)<1e-3f){root=0;return 1;}if(fabsf(vy)<1e-3f){root=vx>0?.5f*BF_PI:-.5f*BF_PI;return 1;}float lo[3],hi[3];if(vx>0){lo[0]=1.4901161e-7f;hi[0]=.5f*BF_PI-1.4901161e-7f;if(hint<.25f*BF_PI&&hint>-.25f*BF_PI){lo[1]=-.25f*BF_PI;hi[1]=-1.4901161e-7f;lo[2]=.5f*BF_PI+1.4901161e-7f;hi[2]=BF_PI-1.4901161e-7f;}else{lo[2]=-.25f*BF_PI;hi[2]=-1.4901161e-7f;lo[1]=.5f*BF_PI+1.4901161e-7f;hi[1]=BF_PI-1.4901161e-7f;}}else{lo[0]=-1.4901161e-7f;hi[0]=-.5f*BF_PI+1.4901161e-7f;if(hint>-.25f*BF_PI&&hint<.25f*BF_PI){lo[1]=.25f*BF_PI;hi[1]=1.4901161e-7f;lo[2]=-.5f*BF_PI-1.4901161e-7f;hi[2]=-BF_PI+1.4901161e-7f;}else{lo[2]=.25f*BF_PI;hi[2]=1.4901161e-7f;lo[1]=-.5f*BF_PI-1.4901161e-7f;hi[1]=-BF_PI+1.4901161e-7f;}}for(int q=0;q<3;q++)if(bf_scan(vx,vy,th,hint,node,lo[q],hi[q],maxcells,root))return 1;root=atan2f(vx,vy);return 0;}
__device__ __forceinline__ df32 bd(double x){float h=(float)x;return{h,(float)(x-(double)h)};}__device__ __forceinline__ df32 bd_min(df32 a,double x){return d32_float(a)<x?a:bd(x);}__device__ __forceinline__ df32 bd_acos(df32 x){df32 y=d32(acosf(fmaxf(-1,fminf(1,d32_float(x)))));for(int k=0;k<2;k++){df32 s,c;d32_sincos(y,s,c);y=d32_add(y,d32_div(d32_sub(c,x),s));}return y;}
__device__ df32 bd_residual(df32 phi,double vx0,double vy0,double th0,unsigned node,int&valid){df32 vx=bd(vx0),vy=bd(vy0),th=bd(th0);if(fabs(vx0)<1e-3||fabs(vy0)<1e-3||fabs(d32_float(phi))<1e-15){valid=1;return d32(0);}df32 alpha=d32_sub(phi,th);float av=d32_float(alpha);while(av>BF_PI){alpha=d32_sub(alpha,bd(2.0*BEM_PI));av=d32_float(alpha);}while(av<-BF_PI){alpha=d32_add(alpha,bd(2.0*BEM_PI));av=d32_float(alpha);}df32 xd=d32_mul(alpha,bd(180.0/BEM_PI));float x=d32_float(xd);unsigned af=bem_node_afid[node],off=bem_af_offset[af],n=bem_af_count[af],lo=0,hi=n-1;if(x<=bem_alpha_deg[off])lo=0;else if(x>=bem_alpha_deg[off+n-1])lo=n-2;else{while(hi-lo>1){unsigned m=(lo+hi)>>1;if(bem_alpha_deg[off+m]<=x)lo=m;else hi=m;}}df32 w=d32_div(d32_sub(xd,bd(bem_alpha_deg[off+lo])),bd(bem_alpha_deg[off+lo+1]-bem_alpha_deg[off+lo]));df32 cl=d32_add(bd(bem_cl[off+lo]),d32_mul(w,bd(bem_cl[off+lo+1]-bem_cl[off+lo]))),s,c;d32_sincos(phi,s,c);df32 as=d32_abs(s),ft=d32(1),fh=d32(1);if(d32_float(as)>0){ft=d32_mul(bd(2.0/BEM_PI),bd_acos(bd_min(d32_exp(d32_div(bd(-bem_node_tip_const[node]),as)),1)));fh=d32_mul(bd(2.0/BEM_PI),bd_acos(bd_min(d32_exp(d32_div(bd(-bem_node_hub_const[node]),as)),1)));}df32 F=d32_mul(ft,fh);if(d32_float(F)<1e-4f)F=bd(1e-4);df32 sigma=bd(3*bem_node_chord[node]/(2*BEM_PI*bem_node_r[node])),cn=d32_mul(cl,c),ct=d32_mul(cl,s),k=d32_div(d32_mul(sigma,cn),d32_mul(bd(4),d32_mul(F,d32_mul(s,s)))),kp;if(fabs(d32_float(c))<1e-15)kp=bd(copysign(1e6,d32_float(ct)*d32_float(s))*copysign(1.0,vx0));else{kp=d32_div(d32_mul(sigma,ct),d32_mul(bd(4),d32_mul(F,d32_mul(s,c))));if(vx0<0)kp=d32_neg(kp);}bool momentum=(d32_float(phi)>0&&vx0>=0)||(d32_float(phi)<0&&vx0<0);valid=1;df32 aa;if(momentum){if(d32_float(k)<=2.0/3){aa=d32_div(k,d32_add(d32(1),k));if(d32_float(k)<-1)valid=0;}else{df32 t=d32_mul(bd(2),d32_mul(F,k)),g1=d32_sub(t,d32_sub(bd(10.0/9.0),F)),g2=d32_sub(t,d32_mul(d32_sub(bd(4.0/3.0),F),F)),g3=d32_sub(t,d32_sub(bd(25.0/9.0),d32_mul(bd(2),F)));aa=fabs(d32_float(g3))<1e-6?d32_s