__device__ double bd_refine(float x0,double vx,double vy,double th,unsigned node){df32 x=bd(x0);for(int k=0;k<4;k++){int v;df32 f=bd_residual(x,vx,vy,th,node,v),h=bd(k<2?1e-4:1e-5),fm=bd_residual(d32_sub(x,h),vx,vy,th,node,v),fp=bd_residual(d32_add(x,h),vx,vy,th,node,v),der=d32_div(d32_sub(fp,fm),d32_mul(d32(2),h)),step=d32_div(f,der);float sv=d32_float(step);if(!d32_finite(step)||fabsf(sv)>.02f)step=bd(copysign(.02,sv));x=d32_sub(x,step);}return (double)x.hi+(double)x.lo;}
